Lang["Q2_2041"] = "Sprecht mit Shoni der Schtillen in Stormwind."
Lang["Q2_214"] = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt."
Lang["Q2_2198"] = "Sucht den ursprünglichen Schöpfer der zerrissenen Halskette auf, um ihren Wert zu erfahren."
Lang["Q2_220"] = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens."
Lang["Q2_2200"] = "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."
Lang["Q2_2201"] = "Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat."
Lang["Q2_2202"] = "Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld."
Lang["Q2_2204"] = "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab."
Lang["Q2_2205"] = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks."
Lang["Q2_2206"] = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw."
Lang["Q2_2218"] = "Speak with Hulfdan Blackbeard in Ironforge."
Lang["Q2_2238"] = "Find Onin MacHammar by Gnomeregan."
Lang["Q2_2239"] = "Take Onin's Report back to Hulfdan in Ironforge."
Lang["Q2_2240"] = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht."
Lang["Q2_2241"] = "Take Jannok's Rose to Syurna in Darnassus."
Lang["Q2_2242"] = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna."
Lang["Q2_2258"] = "Bringt 5 Bussardinnerein, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter nach Kargath zu Jarkal Mossmeld."
Lang["Q2_2259"] = "Contact Erion Shadewhisper in Darnassus."
Lang["Q2_2260"] = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\""
Lang["Q2_2278"] = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon."
Lang["Q2_2279"] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge."
Lang["Q2_2280"] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff."
Lang["Q2_2281"] = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius."
Lang["Q2_2282"] = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire."
Lang["Q2_2283"] = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt."
Lang["Q2_2284"] = "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine."
Lang["Q2_2298"] = "Travel to Stormwind and seek out Renzik \"The Shiv.\""
Lang["Q2_2299"] = "Travel to Ironforge and speak with Hulfdan Blackbeard."
Lang["Q2_2300"] = "Travel to Stormwind and seek out Renzik \"The Shiv.\""
Lang["Q2_2318"] = "Findet jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächste Ort ist Kargath im Ödland."
Lang["Q2_2339"] = "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet."
Lang["Q2_2342"] = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity."
Lang["Q2_2359"] = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower."
Lang["Q2_2360"] = "Travel to Westfall and find Agent Kearnen for your debriefing."
Lang["Q2_2378"] = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow."
Lang["Q2_2379"] = "Speak with Zando'zan at the Cleft of Shadow."
Lang["Q2_2380"] = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar."
Lang["Q2_2381"] = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!"
Lang["Q2_2382"] = "Travel to Ratchet and speak with Wrenix the Wretched."
Lang["Q2_2383"] = "Read the Simple Parchment and speak to Frang in the Valley of Trials."
Lang["Q2_2398"] = "Sucht in Uldaman nach Baelog."
Lang["Q2_2418"] = "Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum."
Lang["Q2_2458"] = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize."
Lang["Q2_2460"] = "Perform the Shattered Salute on Shenthul."
Lang["Q2_2478"] = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction."
Lang["Q2_2479"] = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"
Lang["Q2_2480"] = "Wait for Serge Hinott to complete the cure."
Lang["Q2_2500"] = "Bringt 5 Bussardinnerein, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter nach Thelsamar zu Ghak Heiltouch."
Lang["Q2_26"] = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."
Lang["Q2_2607"] = "Speak with Doc Mixilpixil in the cellar of the Barracks."
Lang["Q2_2608"] = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?"
Lang["Q2_2609"] = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young  fella:lady;."
Lang["Q2_261"] = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück."
Lang["Q2_27"] = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."
Lang["Q2_272"] = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade."
Lang["Q2_275"] = "Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands."
Lang["Q2_276"] = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels for Rethiel the Greenwarden in the Wetlands."
Lang["Q2_2768"] = "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle."
Lang["Q2_277"] = "Bring Rethiel the Greenwarden 9 Crude Flints."
Lang["Q2_2770"] = "Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe."
Lang["Q2_28"] = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial."
Lang["Q2_2841"] = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar."
Lang["Q2_2842"] = "Sprecht mit Scooty in Booty Bay."
Lang["Q2_2843"] = "Wartet, bis Scooty den Goblin-Transponder kalibriert hat."
Lang["Q2_2846"] = "Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow."
Lang["Q2_2865"] = "Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen."
Lang["Q2_29"] = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial."
Lang["Q2_2904"] = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay."
Lang["Q2_2922"] = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge."
Lang["Q2_2923"] = "Sprecht mit Tüftlermeister Overspark in Ironforge."
Lang["Q2_2924"] = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe."
Lang["Q2_2926"] = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück."
Lang["Q2_2927"] = "Sprecht mit Ozzie Togglevolt in Kharanos."
Lang["Q2_2928"] = "Bringt 24 robomechanische Innereien zu Shoni nach Stormwind."
Lang["Q2_2929"] = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist."
Lang["Q2_2933"] = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle."
Lang["Q2_2934"] = "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel."
Lang["Q2_2935"] = "Sprecht mit Meister Gadrin in Sen'jin."
Lang["Q2_2936"] = "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück."
