Lang["Q2_5722"] = "Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen."
Lang["Q2_5723"] = "Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück."
Lang["Q2_5724"] = "Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff."
Lang["Q2_5725"] = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity."
Lang["Q2_5726"] = "Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar."
Lang["Q2_5727"] = "Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück."
Lang["Q2_5728"] = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt."
Lang["Q2_5729"] = "Sprecht mit Neeru Fireblade in Orgrimmar."
Lang["Q2_5730"] = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt."
Lang["Q2_5742"] = "Hört Euch an, was Tirion Fordring zu sagen hat."
Lang["Q2_5761"] = "Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar."
Lang["Q2_5781"] = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."
Lang["Q2_5845"] = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."
Lang["Q2_5846"] = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte."
Lang["Q2_5848"] = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind."
Lang["Q2_5921"] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_5922"] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_5923"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_5924"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_5925"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_5926"] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."
Lang["Q2_5927"] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."
Lang["Q2_5928"] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."
Lang["Q2_5929"] = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade."
Lang["Q2_5930"] = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade."
Lang["Q2_5931"] = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave."
Lang["Q2_5932"] = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise."
Lang["Q2_5961"] = "Sprecht mit Nathanos Blightcaller in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte."
Lang["Q2_6001"] = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done."
Lang["Q2_6002"] = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done."
Lang["Q2_6022"] = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."
Lang["Q2_6042"] = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid."
Lang["Q2_6061"] = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6062"] = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill."
Lang["Q2_6063"] = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6064"] = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."
