Lang["Q2_6082"] = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill."
Lang["Q2_6083"] = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill."
Lang["Q2_6084"] = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos."
Lang["Q2_6085"] = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."
Lang["Q2_6086"] = "Speak with Belia Thundergranite in Ironforge."
Lang["Q2_6087"] = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6088"] = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6089"] = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff."
Lang["Q2_6101"] = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6102"] = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6103"] = "Speak to Jocaste in the Cenarion Enclave, in Darnassus."
Lang["Q2_6121"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6122"] = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore."
Lang["Q2_6123"] = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve."
Lang["Q2_6124"] = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins."
Lang["Q2_6125"] = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_6126"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6127"] = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens."
Lang["Q2_6128"] = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve."
Lang["Q2_6129"] = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads."
Lang["Q2_6130"] = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff."
Lang["Q2_6133"] = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge.Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten."
Lang["Q2_6135"] = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller.Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift."
Lang["Q2_6136"] = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt."
Lang["Q2_6141"] = "Sprecht mit Bruder Anton in Desolace."
Lang["Q2_6144"] = "Reist in die Undercity und sprecht mit Varimathras."
Lang["Q2_6163"] = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos."
Lang["Q2_63"] = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest."
Lang["Q2_65"] = "Gryan Stoutmantle möchte, dass Ihr in Seenhain mit Wiley sprecht."
Lang["Q2_6521"] = "Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity."
Lang["Q2_6522"] = "Bringt die kleine Rolle zu Varimathras nach Undercity."
Lang["Q2_65593"] = "Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten."
Lang["Q2_65597"] = "Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Undercity zurück."
Lang["Q2_65601"] = "Sprecht mit Magar in Orgrimmar."
Lang["Q2_65602"] = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind."
Lang["Q2_65603"] = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück."
Lang["Q2_65604"] = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Bloodeye in Orgrimmar zurück."
Lang["Q2_6561"] = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff."
Lang["Q2_65610"] = "Untersucht den Fallenskysee in Ashenvale und erstattet Gan'rul Bloodeye in Orgrimmar Bericht."
Lang["Q2_6562"] = "Sprecht in Ashenvale mit Je'neu Sancrea."
Lang["Q2_6563"] = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale."
Lang["Q2_6564"] = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale."
Lang["Q2_6565"] = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück."
Lang["Q2_6626"] = "Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück."
Lang["Q2_6627"] = "Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid."
Lang["Q2_6628"] = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid."
Lang["Q2_6681"] = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared."
Lang["Q2_6701"] = "Syndicate Emblems"
Lang["Q2_6921"] = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."
Lang["Q2_6922"] = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."
Lang["Q2_6981"] = "Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann."
Lang["Q2_7028"] = "Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace."
Lang["Q2_7029"] = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon."
Lang["Q2_7041"] = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon."
Lang["Q2_7044"] = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten."
Lang["Q2_7046"] = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt."
Lang["Q2_7064"] = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück."
Lang["Q2_7065"] = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück."
Lang["Q2_7066"] = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens."
Lang["Q2_7067"] = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."
Lang["Q2_7068"] = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar."
Lang["Q2_7070"] = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow."
Lang["Q2_709"] = "Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh."
Lang["Q2_720"] = "Findet Ausgrabungsleiter Ryedol und lasst ihn wissen, dass Hammertoe Grez am Leben ist."
Lang["Q2_7201"] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."
Lang["Q2_721"] = "Sucht in Uldaman nach Hammertoe Grez."
Lang["Q2_722"] = "Sucht Hammertoes Amulett und bringt es ihm nach Uldaman."
Lang["Q2_7441"] = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben."
Lang["Q2_7461"] = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen."
Lang["Q2_7462"] = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!"
Lang["Q2_7481"] = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache."
Lang["Q2_7482"] = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon."
Lang["Q2_7488"] = "Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas."
Lang["Q2_7489"] = "Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas."
Lang["Q2_7492"] = "Sprecht mit Talo Thornhoof im Camp Mojache in Feralas."
Lang["Q2_7494"] = "Sprecht mit Latronicus Moonspear in der Festung Feathermoon in Feralas."
Lang["Q2_7499"] = "Return the book to its rightful owners."
Lang["Q2_7506"] = "Return the book to its rightful owners."
Lang["Q2_7562"] = "Sprecht mit Mor'zul Bloodbringer in der brennenden Steppe."
Lang["Q2_7563"] = "Mor'zul Bloodbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt."
Lang["Q2_7564"] = "Bringt den Behälter mit Blut zu Gorzeeki Wildeyes in der brennenden Steppe."
Lang["Q2_7581"] = "Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der faulenden Narbe zurück."
Lang["Q2_7582"] = "Reist in die flüsternde Schlucht in Winterspring und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt."
Lang["Q2_7583"] = "Wagt Euch in die faulende Narbe heraus und macht einen Kommandant der Verdammniswache ausfindig.\n\nWendet das leuchtende Kristallgefängnis auf den Kommandanten der Verdammniswache an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.\n\nSolltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der faulenden Narbe."
Lang["Q2_7601"] = "Sprecht mit Impsy im Teufelswald."
Lang["Q2_7602"] = "Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\n\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region.\n\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald."
Lang["Q2_7603"] = "Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\n\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald."
Lang["Q2_7621"] = "A Warning"
Lang["Q2_7622"] = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain."
Lang["Q2_7623"] = "Erwerbt schattenhaftige Tränke von Gorzeeki in der brennenden Steppe.\n\nBenutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Banehollow."
Lang["Q2_7624"] = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Banehollow in Jaedenar."
Lang["Q2_7625"] = "Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki in der brennenden Steppe."
Lang["Q2_7626"] = "Bringt 10 Elixiere der Schattenmacht zu Gorzeeki Wildeyes in die brennende Steppe."
Lang["Q2_7627"] = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildeyes in die brennende Steppe."
Lang["Q2_7628"] = "Bringt 35 Schuppen eines schwarzen Drachen zu Gorzeeki Wildeyes in der brennenden Steppe."
Lang["Q2_7629"] = "Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildeyes."
Lang["Q2_7630"] = "Bringt 3 Arkanitbarren zu Gorzeeki in der brennenden Steppe."
Lang["Q2_7631"] = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch."
Lang["Q2_7632"] = "Find the owner of the Ancient Petrified Leaf. Good luck, you; It's a big world."
Lang["Q2_7633"] = "An Introduction"
Lang["Q2_7634"] = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."
Lang["Q2_7635"] = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."
Lang["Q2_7636"] = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself."
Lang["Q2_7637"] = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."
Lang["Q2_7638"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_7639"] = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7640"] = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7641"] = "Speak with Grimand Elmore in Stormwind's Dwarven District."
Lang["Q2_7642"] = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."
Lang["Q2_7643"] = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."
Lang["Q2_7644"] = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7645"] = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities."
Lang["Q2_7646"] = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7647"] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."
Lang["Q2_7648"] = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."
Lang["Q2_7666"] = "Again Into the Great Ossuary"
Lang["Q2_7667"] = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."
Lang["Q2_7668"] = "The Darkreaver Menace"
Lang["Q2_7669"] = "Again Into the Great Ossuary"
Lang["Q2_7670"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_78916"] = "Bringt die Perle der Blackfathom-Tiefe zu Dämmerbehüter Selgorm in Darnassus."
Lang["Q2_78917"] = "Bringt die Perle der Blackfathom-Tiefe zu Bashana Runentotem in Donnerfels."
Lang["Q2_79007"] = "Reist nach 46, 73 im Brachland. Interagiert mit den ausgebrannten Überresten und nehmt die Quest an.\n\nGebt sie bei 37, 50 in Westfall ab, indem Ihr mit der festgenagelten Planke interagiert. Nehmt Trittsteine von dieser Planke an, bevor Ihr geht."
Lang["Q2_79008"] = "Reist nach 37, 50 in Westfall. Interagiert mit den ausgebrannten Überresten neben der festgenagelten Planke und nehmt die Quest an.\n\nGebt sie bei 46, 73 im Brachland an den ausgebrannten Überresten ab, interagiert dann dort mit der festgenagelten Planke und nehmt Trittsteine an."
Lang["Q2_79192"] = "Die Horde nimmt dies an der festgenagelten Planke bei 37, 50 in Westfall an. Die Allianz nimmt es an der festgenagelten Planke bei 46, 73 im Brachland an.\n\nReist nach 51, 51 im Steinkrallengebirge. Folgt von der Straße aus der Öffnung in die Berge und dem Pfad bis zum Lager. Interagiert mit dem Tascheninhalt (40.8, 52.5)."
Lang["Q2_79974"] = "Interagiert mit dem Erdhügel im Steinkrallengebirge (39.6, 49.9), um diese Quest anzunehmen.\n\nReist zum Damm bei 49, 12 in Loch Modan. Springt zum Vorsprung hinab und interagiert mit der geschnitzten Figur (49.5, 12.8)."
Lang["Q2_79975"] = "Interagiert mit der geschnitzten Figur am Damm von Loch Modan (49.5, 12.8), um diese Quest anzunehmen.\n\nReist nach 81, 56 im Vorgebirge von Hillsbrad. Wenn Ihr zum Tor ins Arathihochland blickt, biegt links ab und folgt der Mauer bis zum umgestürzten Wagen. Folgt dem Sprungrätsel zum Lager und interagiert dann mit der Kuriertasche (Arathihochland 22.4, 24.2)."
Lang["Q2_79976"] = "Interagiert mit der Kuriertasche und danach mit dem hastig zusammengerollten Beutel direkt darunter, um den Gemütlichen Schlafsack zu erhalten."
Lang["Q2_79980"] = "Interagiert im Lager des Steinkrallengebirges mit dem Tascheninhalt (40.8, 52.5), um diese Quest anzunehmen.\n\nLauft durch das Lager und springt die Berge hinab zu dem Vorsprung mit dem Erdhügel (39.6, 49.9), dann interagiert damit."
Lang["Q2_79987"] = "Ihr könnt den Ring behalten oder die Person finden, die für den Abdruck und die Gravuren auf der Innenseite verantwortlich ist."
Lang["Q2_80140"] = "Ihr könnt den Ring behalten oder die Person finden, die für den Abdruck und die Gravuren auf der Innenseite verantwortlich ist."
Lang["Q2_80324"] = "Bringt Thermapluggs Ingenieursnotizen zu Hochtüftler Mekkatorque in Tüftlerstadt in Eisenschmiede."
Lang["Q2_80325"] = "Bringt Thermapluggs Ingenieursnotizen zu Nogg im Tal der Ehre in Orgrimmar."
Lang["Q2_8151"] = "Speak to Ogtinc in Azshara."
Lang["Q2_8153"] = "Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath."
Lang["Q2_8231"] = "Bring 6 Wavethrasher Scales to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."
Lang["Q2_8232"] = "Bring the Tooth of Morphaz to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."
Lang["Q2_8233"] = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor."
Lang["Q2_8234"] = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara."
Lang["Q2_8235"] = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara."
Lang["Q2_8236"] = "Return the Azure Key to Lord Jorach Ravenholdt."
Lang["Q2_8249"] = "Junkboxes Needed"
Lang["Q2_8250"] = "Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem."
Lang["Q2_8251"] = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben."
Lang["Q2_8252"] = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem."
Lang["Q2_8253"] = "Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück."
Lang["Q2_8254"] = "Seek out Ogtinc in Azshara."
Lang["Q2_8255"] = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."
Lang["Q2_8256"] = "Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."
Lang["Q2_8257"] = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows."
Lang["Q2_8258"] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.\n\nBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."
Lang["Q2_8259"] = "A More Fitting Reward"
Lang["Q2_8328"] = "Mage Training"
Lang["Q2_8344"] = "Windows to the Source"
Lang["Q2_8410"] = "Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher."
Lang["Q2_8411"] = "Bring the elements earth, air, fire and water to Bath'rah the Windwatcher."
Lang["Q2_8412"] = "Bring the pieces for the spirit totem to Bath'rah the Windwatcher."
Lang["Q2_8413"] = "Bring the voodoo feathers to Bath'rah the Windwatcher."
Lang["Q2_8414"] = "Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."
Lang["Q2_8415"] = "Speak to Commander Ashlam Valorfist at Chillwind Camp."
Lang["Q2_8416"] = "Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point."
Lang["Q2_8417"] = "Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."
Lang["Q2_8418"] = "Bring the voodoo feathers to Ashlam Valorfist."
Lang["Q2_8419"] = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."
Lang["Q2_8420"] = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."
Lang["Q2_8421"] = "Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald."
Lang["Q2_8422"] = "Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel."
Lang["Q2_8423"] = "Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde."
Lang["Q2_8424"] = "Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde."
Lang["Q2_8425"] = "Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde."
Lang["Q2_8563"] = "Warlock Training"
Lang["Q2_8564"] = "Priest Training"
Lang["Q2_865"] = "Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet."
Lang["Q2_870"] = "Berichtet Tonga Runetotem von Euren Entdeckungen."
Lang["Q2_877"] = "Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt."
Lang["Q2_880"] = "Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen."
Lang["Q2_886"] = "Sprecht in Crossroads mit Tonga Runetotem."
Lang["Q2_9051"] = "Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task."
Lang["Q2_9052"] = "Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."
Lang["Q2_9053"] = "Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder."
Lang["Q2_9063"] = "Speak with Torwa Pathfinder in Un'Goro Crater."
Lang["Q2_914"] = "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane."
Lang["Q2_92401"] = "Untersucht das Verschwinden von Edward Heartweaver in den Ruinen von Lordaeron."
Lang["Q2_92415"] = "Bringt den blutbefleckten Brief zu Waisenmatrone Nightingale in Stormwind."
Lang["Q2_92421"] = "Sammelt 25 intakte Gliedmaßen in den Ruinen von Lordaeron für Morbin Lightbane in Undercity."
Lang["Q2_92422"] = "Tötet Rath'mael in den Ruinen von Lordaeron für Todeswache Kristof in Brill."
Lang["Q2_92432"] = "Erstattet dem Abbild der Erzmagierin Modera nahe der Stadt Dalaran Bericht."
Lang["Q2_92434"] = "Findet einen Weg nach Dalaran am Ufer des Lordameresees."
Lang["Q2_92456"] = "Sammelt eine teufelsdurchdrungene Blüte in der Stadt Dalaran für Shylamiir in Stormwind."
Lang["Q2_92458"] = "Sammelt den Arkanpartikel für das Abbild der Erzmagierin Modera nahe der Stadt Dalaran."
Lang["Q2_92459"] = "Speak to Archmage Celindra in the City of Dalaran."
Lang["Q2_92489"] = "Erschlagt den Manaelementar in der Stadt Dalaran für Hochzauberer Andromath in Stormwind."
Lang["Q2_92742"] = "Nutzt das Set für Brunnenwasserproben, um Proben aus den Brunnen auf Jansens Hof und Molsens Hof zu sammeln."
